contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We accept parameters: amount to send and a dummy extra to vary calldata; function is payable
    function run(uint sendAmount, uint dummy) public payable {
        // ensure this contract has enough balance to forward sendAmount
        require(address(this).balance >= sendAmount);

        // read observables before the call
        address bankBefore = c.bank();
        uint potBefore = c.pot();
        uint contractBalanceBefore = address(c).balance;

        bool reverted;
        // perform the state-changing call; capture revert
        try c.play{value: sendAmount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read observables after the call
        address bankAfter = c.bank();
        uint potAfter = c.pot();
        uint contractBalanceAfter = address(c).balance;

        // The general rule:
        // - bank address never changes
        // - if call reverted then sendAmount != TICKET_AMOUNT and no state change to pot or contract balance
        // - if call did not revert and sendAmount == TICKET_AMOUNT then either:
        //    * pot increased by sendAmount (no payout branch taken), or
        //    * pot became 0 and contractBalance increased by (potBefore - c.FEE_AMOUNT()) and contractBalanceBefore decreased by sendAmount (the forwarded ticket) is captured by c balance change; equivalently contractBalanceAfter == contractBalanceBefore + potBefore - c.FEE_AMOUNT()

        // Compose the assertion expressing above. Note: access to constants via c.TICKET_AMOUNT() and c.FEE_AMOUNT().
        assert(
            bankBefore == bankAfter &&
            (
                // reverted case: no state change to pot or contract balance and sendAmount != TICKET_AMOUNT
                (reverted && sendAmount != c.TICKET_AMOUNT() && potBefore == potAfter && contractBalanceBefore == contractBalanceAfter)
                ||
                // non-reverted case: sendAmount must equal TICKET_AMOUNT
                (!reverted && sendAmount == c.TICKET_AMOUNT() && (
                    // either pot simply increased by ticket amount
                    potAfter == potBefore + sendAmount
                    ||
                    // or payout branch executed: pot becomes zero and contract (c) balance increased by potBefore - FEE
                    (potAfter == 0 && contractBalanceAfter == contractBalanceBefore + (potBefore - c.FEE_AMOUNT()))
                ))
            )
        );
    }

    // allow receiving Ether when c pays out to this contract
    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // sendAmount is the ether forwarded to c.play; dummy varies calldata but unused
    function run(uint sendAmount, uint /*dummy*/ ) public payable {
        // ensure this contract has enough balance to forward sendAmount
        require(address(this).balance >= sendAmount);

        // observe before state
        address bankBefore = c.bank();
        uint potBefore = c.pot();
        uint balanceBefore = address(c).balance;

        bool reverted;
        // attempt the state-changing call and capture whether it reverted
        try c.play{value: sendAmount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // observe after state
        address bankAfter = c.bank();
        uint potAfter = c.pot();
        uint balanceAfter = address(c).balance;

        // Constants known from contract C (per reference): TICKET_AMOUNT = 10, FEE_AMOUNT = 1
        uint TICKET = 10;
        uint FEE = 1;

        // General rule asserted:
        // - bank address never changes
        // - call reverts iff sendAmount != 10
        // - if not reverted (sendAmount == 10) then either pot increased by 10, or pot became 0 and c's balance increased by (potBefore - 1)
        assert(
            bankBefore == bankAfter &&
            (
                (reverted && sendAmount != TICKET && potBefore == potAfter && balanceBefore == balanceAfter)
                ||
                (!reverted && sendAmount == TICKET && (
                    potAfter == potBefore + TICKET
                    ||
                    (potAfter == 0 && balanceAfter == balanceBefore + (potBefore - FEE))
                ))
            )
        );
    }

    // Allow receiving Ether if C pays out to this contract
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        require(address(this).balance >= amount);
        // observe before-values
        address bankBefore = c.bank();
        uint potBefore = c.pot();
        uint balanceCBefore = address(c).balance;
        uint totalBefore = balanceCBefore + potBefore; // total Ether accounted in c

        bool reverted;
        // call play sending `amount` wei
        try c.play{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // observe after-values
        address bankAfter = c.bank();
        uint potAfter = c.pot();
        uint balanceCAfter = address(c).balance;
        uint totalAfter = balanceCAfter + potAfter;

        // General rule:
        // - bank address must never change
        // - if call reverted then totals unchanged; if not reverted then totalAfter == totalBefore + amount - (address(bank) received from this contract in the call)
        // However we cannot directly read bank's balance, so we express a weaker invariant:
        // If the call reverted then totalAfter == totalBefore. If it did not revert then totalAfter <= totalBefore + amount and totalAfter >= totalBefore.
        // This captures that a non-reverting play cannot create Ether out of nothing and total funds in contract+pot only increase by at most the sent amount and never decrease below previous total.

        assert(bankAfter == bankBefore && (reverted ? totalAfter == totalBefore : (totalAfter >= totalBefore && totalAfter <= totalBefore + amount)));
    }

    receive() external payable { }
}
